import test from 'node:test';import assert from 'node:assert/strict';import {applyPrototypeCommand} from './prototype-commands.js';
const state=()=>({prototypeState:{students:[{id:'e1',titulares:['p1','p2']},{id:'e2',titulares:['p3']}],requests:[{id:'r1',studentId:'e1',status:'aprobada'},{id:'r2',studentId:'e2',status:'aprobada'}],busTrips:{trip:{noBus:[]}}}});const parent={role:'parent',prototypeIdentity:{personId:'p1'}};
test('narrow commands mutate only linked household records',()=>{const s=state();const confirmed=applyPrototypeCommand(s,parent,{type:'confirm_pickup',requestId:'r1',confirmed:true});assert.equal(confirmed.requests[0].confirmation.status,'confirmada');assert.throws(()=>applyPrototypeCommand(s,parent,{type:'cancel_request',requestId:'r2'}),/forbidden_request_family/)});
test('narrow bus command accepts own child and rejects another family',()=>{const s=state();assert.deepEqual(applyPrototypeCommand(s,parent,{type:'bus_opt_out',tripKey:'trip',studentId:'e1'}).busTrips.trip.noBus,['e1']);assert.throws(()=>applyPrototypeCommand(s,parent,{type:'bus_opt_out',tripKey:'trip',studentId:'e2'}),/forbidden_parent_bus_family/)});
